async function shuffleSelf(x) {
  const g = x.g, p = x.me; if (!g.slots(p).includes(x.att)) return;
  const wasActive = p.active === x.att;
  if (wasActive && !p.bench.length) return; // no puede quedarse sin Pokémon
  g.shuffleSlotIntoDeck(x.att); g.log(`${x.name} vuelve al mazo.`);
  if (wasActive) { const n = await g.ask(p, { kind: 'slot', title: 'Elige tu nuevo Pokémon Activo', options: p.bench.slice(), purpose: 'newActive' }); await g.switchActive(p, n || p.bench[0]); }
}
L.forEach((e, i) => { A[i] = e; });
root.PTCG.ATK_ES = L.map(e => e.es);
